X0     = -785.92042
Y_TOP  = 182.0217
CELL_W = 1.59482
CELL_H = 1.85936
NROW, NCOL = 57, 66
TRANSFORM = "matrix(0.26458333,0,0,0.26458334,207.98849,-47.63304)"

PAGE_W_MM, PAGE_H_MM = 27.968896, 28.1314829
BORDER = dict(x=-785.99805, y=180.13057, w=105.50883, h=106.123316, sw=0.200386)


def _hex2rgb(h):
    h = h.lstrip("#")
    return [int(h[i:i+2], 16) for i in (0, 2, 4)]


def _blend(base_hex, t):
    """White -> base_hex at fraction t (0..1), as #rrggbb."""
    br, bg, bb = _hex2rgb(base_hex)
    return "#%02x%02x%02x" % (
        round(255 + (br - 255) * t),
        round(255 + (bg - 255) * t),
        round(255 + (bb - 255) * t),
    )


def column_hues():
    hues = []
    for hue, n in BANDS:
        hues += [hue] * n
    assert len(hues) == NCOL, (len(hues), NCOL)
    return hues


def build_svg():
    hues = column_hues()
    paths, pid = [], 2
    for i in range(NROW):
        y_bottom = Y_TOP + i * CELL_H
        for j in range(NCOL):
            x = X0 + j * CELL_W
            fill = _blend(hues[j], VALUES[i][j])
            d = "m %.5f,%.6f h %.5f v -%.5f h -%.5f z" % (
                x, y_bottom, CELL_W, CELL_H, CELL_W)
            paths.append(
                '<path id="path%d" d="%s" style="fill:%s;fill-opacity:1;'
                'fill-rule:nonzero;stroke:none;stroke-width:0.383373" />'
                % (pid, d, fill))
            pid += 1

    border = ('<rect style="fill:none;stroke:#000000;stroke-width:%(sw)s;'
              'stroke-linejoin:bevel;stroke-opacity:1" id="rect3" '
              'width="%(w)s" height="%(h)s" x="%(x)s" y="%(y)s" />') % BORDER

    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n'
        '<svg xmlns="http://www.w3.org/2000/svg" '
        'xmlns:svg="http://www.w3.org/2000/svg" '
        'width="%(W)smm" height="%(H)smm" '
        'viewBox="0 0 %(W)s %(H)s" version="1.1" id="svg1">\n'
        '  <g id="g1" transform="%(T)s">\n    %(border)s\n%(body)s\n  </g>\n'
        '</svg>\n'
    ) % dict(W=PAGE_W_MM, H=PAGE_H_MM, T=TRANSFORM, border=border,
             body="\n".join(paths))


if __name__ == "__main__":
    import sys
    out = sys.argv[1] if len(sys.argv) > 1 else "first_mat_only_v2.svg"
    with open(out, "w") as fh:
        fh.write(build_svg())
    print("wrote", out)
